import{_ as s,a0 as u,w as p,s as b,I as l,x as e,a1 as r,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const A=JSON.parse('{"title":"Web 的成長，就是一篇瀏覽器的故事 | LCTT x X-CMD","titleTemplate":false,"description":"Web 的成長，就是一篇瀏覽器的故事 | LCTT (202102) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Web 的成長，就是一篇瀏覽器的故事 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Web 的成長，就是一篇瀏覽器的故事 | LCTT (202102) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202102/20190312 When the web grew up- A browser story","title":"Web 的成長，就是一篇瀏覽器的故事","tag":"202102","desc":""},"relativePath":"202102/20190312 When the web grew up- A browser story.md","filePath":"[post].md"}'),E={name:"202102/20190312 When the web grew up- A browser story.md"};function i(m,t,f,d,w,C){const n=u("Link");return p(),b("div",null,[t[27]||(t[27]=l("h1",{id:"web-的成長-就是一篇瀏覽器的故事",tabindex:"-1"},[e("Web 的成長，就是一篇瀏覽器的故事 "),l("a",{class:"header-anchor",href:"#web-的成長-就是一篇瀏覽器的故事","aria-label":"Permalink to “Web 的成長，就是一篇瀏覽器的故事”"},"​")],-1)),t[28]||(t[28]=l("blockquote",null,[l("p",null,"互聯網誕生之時我的個人故事。")],-1)),t[29]||(t[29]=l("p",null,[l("img",{src:"https://img.linux.net.cn/data/attachment/album/202102/18/161753qb8tytkc6bnxbavn.jpg",alt:""})],-1)),l("p",null,[t[1]||(t[1]=e("最近，我和大家 ",-1)),r(n,{href:"https://opensource.com/article/18/11/how-web-was-won"},{default:o(()=>[...t[0]||(t[0]=[e("分享了",-1)])]),_:1}),t[2]||(t[2]=e(" 我在 1994 年獲得英國文學和神學學位離開大學後，如何在一個人們還不知道 Web 服務器是什麼的世界裏成功找到一份運維 Web 服務器的工作。我説的“世界”，並不僅僅指的是我工作的機構，而是泛指所有地方。Web 那時當真是全新的 —— 人們還正嘗試理出頭緒。",-1))]),l("p",null,[t[4]||(t[4]=e("那並不是説我工作的地方（一家學術出版社）特別“懂” Web。這是個大部分人還在用 28.8K 貓（調製解調器，俗稱“貓”）訪問網頁的世界。我還記得我拿到 33.6K 貓時有多激動。至少上下行速率不對稱的日子已經過去了，",-1)),r(n,{href:"%E5%AE%83%E5%80%91%E5%8F%88%E6%98%AF%E6%80%8E%E9%BA%BC%E5%9B%9E%E4%BE%86%E7%9A%84%EF%BC%9F"},{default:o(()=>[...t[3]||(t[3]=[e("^1",-1)])]),_:1}),t[5]||(t[5]=e(" 以前 1200/300 的帶寬描述特別常見。這意味着（在同一家機構的）印刷人員製作的設計複雜、色彩繽紛、纖毫畢現的文檔是完全不可能放在 Web 上的。我不能允許在網站的首頁出現大於 40k 的 GIF 圖片，這對我們的許多訪問者來説是很難接受的。大於大約 60k 圖片的會作為獨立的圖片，以縮略圖鏈接過去。",-1))]),l("p",null,[t[7]||(t[7]=e("如果説市場部只有這一點不喜歡，那是絕對是輕描淡寫了。更糟的是佈局問題。“瀏覽器決定如何佈局文檔，”我一遍又一遍地解釋，“你可以使用標題或者段落，但是文檔在頁面上如何呈現並不取決於文檔，而是取決於渲染器！”他們想控制這些，想要不同顏色的背景。後來明白了那些不能實現。我覺得我就像是參加了第一次討論層疊樣式表（CSS）的 W3C 會議，並進行了激烈地爭論。關於文檔編寫者應控制佈局的建議真令人厭惡。",-1)),r(n,{href:"%E4%BD%A0%E5%8F%AF%E8%83%BD%E4%B8%8D%E6%9C%83%E9%A9%9A%E8%A8%9D%EF%BC%8C%E6%88%91%E9%82%84%E6%98%AF%E5%9C%A8%E5%91%BD%E4%BB%A4%E5%88%97%E8%A3%8F%E6%9C%80%E9%96%8B%E5%BF%83%E3%80%82"},{default:o(()=>[...t[6]||(t[6]=[e("^2",-1)])]),_:1}),t[8]||(t[8]=e(" CSS 花了一些時間才被人們採用，與此同時，關心這些問題的人搭上了 PDF 這種到處都是安全問題的列車。",-1))]),t[30]||(t[30]=l("p",null,"如何呈現文檔不是唯一的問題。作為一個實體書出版社，對於市場部來説，擁有一個網站的全部意義在於，讓客户（或者説潛在的客户）不僅知道一本書的內容，而且知道買這本書需要花多少錢。但這有一個問題，你看，互聯網，包括快速發展的萬維網，是開放的，是所有都免費的自由之地，沒有人會在意錢；事實上，在那裏談錢是要回避和避免的。",-1)),t[31]||(t[31]=l("p",null,"我和主流“網民”的看法一致，認為沒必要把價格信息放在線上。我老闆，以及機構裏相當多的人都持相反的意見。他們覺得消費者應該能夠看到書要花多少錢。他們也覺得我的銀行經理也會想看到我的賬户裏每個月進了多少錢，如果我不認同他們的觀點的話，那我的收入就可能堪憂。",-1)),l("p",null,[t[10]||(t[10]=e("幸運的是，在我被炒魷魚之前，我已經自己認清了一些 —— 可能是在我開始邁入 Web 的幾星期之後，Web 已經發生變化，有其他人公佈他們的產品價格信息。這些新來者通常被那些從早期就開始運行 Web 服務器的老派人士所看不起，",-1)),r(n,{href:"%E5%A4%A7%E7%B4%84%E5%85%AD%E5%80%8B%E6%9C%88%E5%89%8D%E3%80%82"},{default:o(()=>[...t[9]||(t[9]=[e("^3",-1)])]),_:1}),t[11]||(t[11]=e(" 但很明顯，風向是往那邊吹的。然而，這並不意味着我們的網站就贏得了戰爭。作為一個學術出版社，我們和大學共享一個域名（在 “ac.uk” 下）。大學不太相信發佈價格信息是合適的，直到出版社的一些資深人士指出，普林斯頓大學出版社正在這樣做，如果我們不做……看起來是不是有點傻？",-1))]),t[32]||(t[32]=l("p",null,"有趣的事情還沒完。在我擔任站點管理員（“webmaster@…”）的短短幾個月後，我們和其他很多網站一樣開始看到了一種令人擔憂的趨勢。某些訪問者可以輕而易舉地讓我們的 Web 服務器跪了。這些訪問者使用了新的網頁瀏覽器：網景瀏覽器（Netscape）。網景瀏覽器實在太惡劣了，它居然是多線程的。",-1)),t[33]||(t[33]=l("p",null,"這為什麼是個問題呢？在網景瀏覽器之前，所有的瀏覽器都是單線程。它們一次只進行一個連接，所以即使一個頁面有五張 GIF 圖，[^4] 也會先請求 HTML 基本文件進行解析，然後下載第一張 GIF，完成，接着第二張，完成，如此類推。事實上，GIF 的順序經常出錯，使得頁面加載得非常奇怪，但這也是常規思路。而粗暴的網景公司的人決定，它們可以同時打開多個連接到 Web 服務器，比如説，可以同時請求所有的 GIF！為什麼這是個問題呢？好吧，問題就在於大多數 Web 服務器都是單線程的。它們不是設計來一次進行多個連接的。確實，我們運行的 HTTP 服務的軟件（MacHTTP）是單線程的。儘管我們花錢購買了它（最初是共享軟件），但我們用的這版無法同時處理多個請求。",-1)),t[34]||(t[34]=l("p",null,"互聯網上爆發了大量討論。這些網景公司的人以為他們是誰，能改變世界的運作方式？它應該如何工作？大家分成了不同陣營，就像所有的技術爭論一樣，雙方都用各種技術熱詞互丟。問題是，網景瀏覽器不僅是多線程的，它也比其他的瀏覽器更好。非常多 Web 服務器代碼維護者，包括 MacHTTP 作者 Chuck Shotton 在內，開始坐下來認真地在原有代碼基礎上更新了多線程測試版。幾乎所有人立馬轉向測試版，它們變得穩定了，最終，瀏覽器要麼採用了這種技術，變成多線程，要麼就像所有過時產品一樣銷聲匿跡了。[^6]",-1)),t[35]||(t[35]=l("p",null,"對我來説，這才是 Web 真正成長起來的時候。既不是網頁展示的價格，也不是設計者能定義你能在網頁上看到什麼，[^8] 而是瀏覽器變得更易用，以及成千上萬的瀏覽者向數百萬瀏覽者轉變的網絡效應，使天平向消費者而不是生產者傾斜。在我的旅程中，還有更多故事，我將留待下次再談。但從這時起，我的僱主開始看我們的月報，然後是週報、日報，並意識到這將是一件大事，真的需要關注。",-1)),t[36]||(t[36]=l("p",null,"[^4]: 莽撞，沒錯，但它確實發生了 [^5] [^5]: 噢，不，是 GIF 或 BMP，JPEG 還是個好主意，但還沒有用上。 [^6]: 沒有真正的沉寂：總有一些堅持他們的首選解決方案具有技術上的優勢，並哀嘆互聯網的其他人都是邪惡的死硬愛好者。 [^7] [^7]: 我不是唯一一個説“我還在用 Lynx”的人。 [^8]: 我會指出，為那些有各種無障礙需求的人制造嚴重而持續的問題。",-1)),t[37]||(t[37]=l("hr",null,null,-1)),l("p",null,[t[13]||(t[13]=e("via: ",-1)),r(n,{href:"https://opensource.com/article/19/3/when-web-grew"},{default:o(()=>[...t[12]||(t[12]=[e("https://opensource.com/article/19/3/when-web-grew",-1)])]),_:1})]),l("p",null,[t[18]||(t[18]=e("作者：",-1)),r(n,{href:"https://opensource.com/users/mikecamel"},{default:o(()=>[...t[14]||(t[14]=[e("Mike Bursell",-1)])]),_:1}),t[19]||(t[19]=e(" 選題：",-1)),r(n,{href:"https://github.com/lujun9972"},{default:o(()=>[...t[15]||(t[15]=[e("lujun9972",-1)])]),_:1}),t[20]||(t[20]=e(" 譯者：",-1)),r(n,{href:"https://github.com/XYenChi"},{default:o(()=>[...t[16]||(t[16]=[e("XYenChi",-1)])]),_:1}),t[21]||(t[21]=e(" 校對：",-1)),r(n,{href:"https://github.com/wxy"},{default:o(()=>[...t[17]||(t[17]=[e("wxy",-1)])]),_:1})]),l("p",null,[t[24]||(t[24]=e("本文由 ",-1)),r(n,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[22]||(t[22]=[e("LCTT",-1)])]),_:1}),t[25]||(t[25]=e(" 原創編譯，",-1)),r(n,{href:"https://linux.cn/"},{default:o(()=>[...t[23]||(t[23]=[e("Linux中國",-1)])]),_:1}),t[26]||(t[26]=e(" 榮譽推出",-1))])])}const B=s(E,[["render",i]]);export{A as __pageData,B as default};
